'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app');
const IS_PAGES=location.hostname.endsWith('github.io');
const BASE=IS_PAGES?'/AniNexus':'';
const TZ='America/Sao_Paulo';
const DATA_ENDPOINT='https://graphql.'+'anilist.co';
const state={theme:safeGet('aninexus:theme','dark'),favorites:new Set(safeJSON('aninexus:favorites',[])),list:new Set(safeJSON('aninexus:list',[])),schedule:null,scheduleHash:'',scheduleTimer:null,countdownTimer:null,searchKind:'ANIME',catalog:{page:1,mode:'ALL',search:'',genre:'',sort:'POPULARITY_DESC'},season:null,newsFilter:'ALL'};
function safeGet(k,f=''){try{return localStorage.getItem(k)||f}catch{return f}}
function safeJSON(k,f){try{const s=localStorage.getItem(k);if(!s||s.length>800000)return f;const v=JSON.parse(s);return v??f}catch{return f}}
function safeSet(k,v){try{localStorage.setItem(k,typeof v==='string'?v:JSON.stringify(v))}catch{}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function stripHtml(s=''){const d=document.createElement('div');d.innerHTML=String(s||'');return d.textContent||''}
function fmtNum(n){return new Intl.NumberFormat('pt-BR',{notation:'compact',maximumFractionDigits:1}).format(n||0)}
function score(m){return m?.averageScore?String((m.averageScore/10).toFixed(1)).replace('.0',''):m?.score?String(m.score):''}
function title(m){return m?.title?.english||m?.title?.userPreferred||m?.title?.romaji||m?.title?.native||m?.title||'Título'}
function image(m){return m?.coverImage?.extraLarge||m?.coverImage?.large||m?.cover||''}
function banner(m){return m?.bannerImage||m?.banner||image(m)}
function slug(s='titulo'){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'').slice(0,90)}
function mediaPath(m,type='anime'){return `/${type}/${slug(title(m))}-${m.id}`}
function pathNow(){let p=location.pathname;if(IS_PAGES)p=p.replace(/^\/AniNexus/,'')||'/';return p.replace(/\/+$/,'')||'/'}
function go(path,replace=false){history[replace?'replaceState':'pushState']({},'',BASE+(path==='/'?'/':path));closeDrawer();closeSearch();render()}
function restorePages(){if(!IS_PAGES)return;const u=new URL(location.href),p=u.searchParams.get('p');if(p){u.searchParams.delete('p');history.replaceState({},'',BASE+(p.startsWith('/')?p:'/'+p)+(u.search?'?'+u.searchParams.toString():''))}}
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;$('#toastRoot').append(n);setTimeout(()=>n.remove(),2500)}
function meta(t){document.title=`${t} | AniNexus`}
